# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::WriteSteps do
  include_context "timekeeping entry writes"

  let(:company) { timekeeping_arrange.company }
  let(:user) { timekeeping_arrange.user(company:, role: "employee") }
  let(:project) { timekeeping_arrange.project(company:) }

  def unpublishable_error_for(row)
    described_class.write_outbox([row], 1)
    nil
  rescue Timekeeping::WriteSteps::UnpublishableRows => error
    error
  end

  it "refuses a bad stored source with a 409 that names the field but never echoes the stored value" do
    stored_value = "legacy-token-sk_live_do_not_echo"
    bad = timekeeping_arrange.entry(company:, user:, project:)
    # A checkpoint load can store a value the snapshot rules refuse.
    Entry.find(bad).update_column(:source, stored_value)

    error = unpublishable_error_for(described_class.reserved_rows(company, [bad]).fetch(bad))

    expect(error).to be_a(Timekeeping::WriteSteps::UnpublishableRows)
    expect(OutboxSnapshot.count).to eq(0)
    outcome = error.outcome
    expect(outcome).to be_a(Timekeeping::WriteOutcome)
    expect(outcome.status).to eq(409)
    expect(JSON.parse(outcome.body))
      .to eq("reason" => "unpublishable_entry", "entries" => [{ "entry_id" => bad, "fields" => ["source"] }])
    # The answer and the error text name fields only, so a stored value never leaves in a response or a log line.
    expect(outcome.body).not_to include(stored_value)
    expect(error.message.to_s).not_to include(stored_value)
  end

  it "keeps bad stored metadata contents out of the unpublishable_entry answer" do
    marker = "secret-marker-in-metadata"
    deep = (1..97).reduce({ "leaf" => marker }) { |inner, _| { "n" => inner } }
    bad = timekeeping_arrange.entry(company:, user:, project:)
    Entry.find(bad).update_column(:proof_metadata, deep)

    error = unpublishable_error_for(described_class.reserved_rows(company, [bad]).fetch(bad))

    expect(error).to be_a(Timekeeping::WriteSteps::UnpublishableRows)
    expect(OutboxSnapshot.count).to eq(0)
    expect(JSON.parse(error.outcome.body).fetch("entries")).to eq([{ "entry_id" => bad, "fields" => ["proof_metadata"] }])
    expect(error.outcome.body).not_to include(marker)
    expect(error.message.to_s).not_to include(marker)
  end

  # The bad rows come last, so a check that inserted row by row, or that checked only the first row, would
  # already have queued the valid ones; a partial insert would leave the outbox out of step with storage.
  it "write_outbox raises UnpublishableRows and inserts no row when one stored row of the batch is bad" do
    valid_ids = Array.new(2) { timekeeping_arrange.entry(company:, user:, project:) }
    bad = timekeeping_arrange.entry(company:, user:, project:)
    Entry.find(bad).update_column(:bill_status, "paid")
    rows = described_class.reserved_rows(company, valid_ids + [bad])

    expect { described_class.write_outbox((valid_ids + [bad]).map { |id| rows.fetch(id) }, timekeeping_arrange.current_generation) }
      .to raise_error(Timekeeping::WriteSteps::UnpublishableRows)
    expect(OutboxSnapshot.count).to eq(0)
    expect(Entry.find(bad).bill_status).to eq("paid")
  end

  it "still inserts one outbox row per valid stored entry, equal to OutboxFields.row" do
    first = timekeeping_arrange.entry(company:, user:, project:, duration: 0.0)
    second = timekeeping_arrange.entry(company:, user:, project:, source_metadata: { "rate" => "1.5" })
    rows = described_class.reserved_rows(company, [first, second])

    described_class.write_outbox([rows.fetch(first), rows.fetch(second)], 1)

    expect(OutboxSnapshot.where(id: [first, second]).count).to eq(2)
    expect(OutboxSnapshot.where(id: first).count).to eq(1)
    expected = Timekeeping::OutboxFields.row(rows.fetch(second), generation: 1)
    stored = OutboxSnapshot.find_by!(id: second)
    expect([stored.source, stored.source_metadata, stored.version, stored.generation, stored.locked])
      .to eq(expected.values_at("source", "source_metadata", "version", "generation", "locked"))
  end
end
